import pathlib,json,hashlib
O=pathlib.Path('outputs');cases=[]
for name,suffix in [('natural',''),('no-delay','-no-delay'),('forced-context','-forced-context')]:
 r=json.loads((O/f'Digitone-indexed-context-handoff-queued-arp-crossing{suffix}.json').read_text())
 assert r['failure'] is None and r['halted'] is None and all(r['storage_checks'].values())
 f=r['delayed_note_fixture'];pub=next(x for x in r['events'] if x['kind']=='queue_publish' and x['event']==f['event'] and x['generation']==f['generation'])
 accept=next(x for x in r['events'] if x['kind']=='acceptance' and x['event']==f['event'] and x['generation']==f['generation'])
 q=next(x for x in r['quantizer_calls'] if x['event']==f['event'] and x['generation']==f['generation'])
 p=next(x for x in r['pitch_outputs'] if x['event']==f['event'] and x['generation']==f['generation'] and x['ordinal']>q['ordinal'])
 writer=next(x for x in r['events'] if x['kind']=='backing_write' and x['backing']=='0x407c61e9' and x['incoming_backing']=='0x407b00cc')
 done=next(x for x in r['events'] if x['kind']=='transition_commit_done' and x['ms']>=writer['ms'] and x['backing']==writer['incoming_backing'])
 assert pub['fields'][:3]==[1,1,2] and pub['backing']=='0x407c61e9'
 assert p['fixed_note']==q['expected']<<16
 if name!='no-delay':
  assert pub['ms']<writer['ms']<accept['ms'] and accept['backing']=='0x407b00cc'
  assert any(x['event']==f['event'] and x['generation']==f['generation'] for x in writer['pending_publications'])
 else:assert accept['ms']<writer['ms']
 if name=='forced-context':assert q['word']=='0x800040bd' and p['fixed_note']==56<<16 and r['diagnostic_metadata_injection']['not_natural_capture']
 else:assert pub['metadata']==accept['candidate_at_acceptance']==q['word']=='0x0' and p['fixed_note']==57<<16 and not r.get('diagnostic_metadata_injection')
 assert r['firmware_sha256']=='0de87bf55e6bc48bebef5479e0d054f262fb7a0c7f81052dbd195d38569fdfda'
 cases.append({'case':name,'event':f['event'],'generation':f['generation'],'publication_ms':pub['ms'],'publication_context':pub['metadata'],'publisher_return':pub.get('publisher_return'),'replacement_ms':writer['ms'],'replacement_pc':writer['pc'],'completion_ms':done['ms'],'acceptance_ms':accept['ms'],'context_at_acceptance':accept['candidate_at_acceptance'],'quantizer_context':q['word'],'input_note':q['note'],'output_note':p['fixed_note']//65536,'old_scale_expected':56,'receiving_scale_expected':57,'retained_record':p['record'],'native_arp_eligibility_confirmed_by_helper_execution':True,'diagnostic_metadata_injection':r.get('diagnostic_metadata_injection'),'queue_delay_ticks':f['added_timer_ticks'],'storage_checks':r['storage_checks']})
out={'firmware_modified':False,'test_execution_completed':True,'natural_old_scale_behavior_verified':False,'counterexample_confirmed':True,'physical_timing_verified':False,'cases':cases,'finding':'The type-1 queued event naturally reaches the native arp quantizer after confirmed replacement, but its candidate context is zero already at publication. The same problem occurs without a transition. Diagnostic old-context injection makes the stock acceptance/retained-read/pitch chain output the expected old-scale note.','physical_evidence_available':'User can record stock Digitone audio in Ableton; no recordings received or analyzed yet.','limits':['Native functional PC execution; not cycle-aware physical measurements.','Queue timestamp delay and old/new pattern root/scale values are explicit PC test fixtures. Event eligibility, identity, cached fields and receiving-pattern pointer are not forced.','Forced-context control supplies a private metadata word only to isolate the downstream code; it is not evidence of natural capture.','One observed producer route is a counterexample, not complete producer coverage.','Audio recording can establish output phenomena but cannot measure the internal execution cost of uninstalled hooks.']}
(O/'Digitone-queued-arp-verification-summary.json').write_text(json.dumps(out,indent=2))
lines=['# Digitone OS 1.42: eligible queued-arp verification','', '**The current PC overlay fails the old-scale requirement on this natural queued producer route.** Physical timing remains unverified. The original firmware is unchanged.','', 'The test starts from the existing arp-enabled pattern 2, with root 61/raw scale 0, then requests pattern 1 with root 59/raw scale 5. A real type-1/state-1/track-2 event is delayed in PC RAM. The firmware performs the actual replacement, accepts the same event generation and executes the native arp quantizer. Neither the event eligibility fields nor the pattern pointer is forged.','', '| Control | Publication ms | Replacement ms | Acceptance ms | Quantizer context | Output | Old-scale expected |','|---|---:|---:|---:|---|---:|---:|']
for c in cases:lines.append(f'| {c["case"]} | {c["publication_ms"]:.3f} | {c["replacement_ms"]:.3f} | {c["acceptance_ms"]:.3f} | {c["quantizer_context"]} | {c["output_note"]} | {c["old_scale_expected"]} |')
lines+=['', 'In the natural crossing, event 0x4199dadc/generation 1 remains pending at the replacement and is accepted afterward without recycling. Its context is already zero when published, remains zero at acceptance and is zero at the native quantizer. The helper therefore falls back to note 57. Its initiating pattern would constrain that note to 56. The receiving scale also allows 57, so the zero word and helper trace—not output alone—identify missing context.','', 'The no-delay control produces the same zero-context fallback before any replacement. This rules out pattern replacement as a necessary cause of this failure. A separate diagnostic supplies 0x800040bd at commit; the actual retained commit/read and quantizer then output 56 after replacement. This control verifies that supplying the original context closes this particular downstream failure, while leaving natural producer capture unimplemented.','', 'The natural publisher returns to 0x40093900. At the corresponding cached-emission branch, 0x40093892 calls the raw 72-byte copy routine 0x400ec23c, and 0x400938fe invokes the queue publisher. This differs from the producer-capture hook at 0x40093ef4. A 72-byte event copy does not itself copy the separate private context array. The exact source-cache ownership and a correct metadata capture/copy hook still need auditing before implementation.','', 'All three runs complete without a halt or unexpected reserved-region writes; helper bytes and guards stay intact. Zero context is a fallback to unchanged pitch, rather than a proven scale lock.','', '## Physical timing and Ableton','', 'No hardware recording or internal timing measurement has been received. The user can record the unchanged Digitone output in Ableton. That supports a stock output baseline, observed sustain/pattern behavior and investigation of candidate audio discontinuities. It does not measure processor/cache timing or prove modified-code deadlines, because the proposed hooks have not executed on the device.','', 'Use [the stock recording protocol](Digitone-Ableton-stock-recording-protocol.md) to collect original WAV files and recording settings. Stock audio observations and modeled margins must remain separate from measured modified-device timing.','', '## Next step','', 'Audit and connect natural context capture/copy for the producer whose publisher returns to 0x40093900, then repeat the natural queued-arp crossing without injected metadata. Physical output analysis can proceed when the Ableton recordings are supplied. No installable firmware was produced.']
(O/'Digitone-queued-arp-verification-audit.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(json.dumps({'counterexample':True,'old_scale_pass':False,'physical_timing_verified':False,'cases':cases},indent=2))
